INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(698,'deDE','Naralex schläft wieder!$b$bVor langer Zeit reiste Naralex mit dem hehren Ziel zu dieser Höhle, in den Smaragdgrünen Traum einzutreten und aus dem Brachland wieder einen üppigen Wald werden zu lassen. Seine Konzentration nahm ab und seine Gedanken wurden von Visionen von Schlangen besudelt.$b$bJetzt sickern reptilienartige Bestien aus seinen Träumen in die Realität. Er muss aus seinem Alptraum erweckt werden, ansonsten wäre er für immer verloren und etwas sehr Böses wäre entfesselt.$b$bErst, wenn seine verderbten Diener, die Giftzahnlords, tot sind, kann ich das Erweckungsritual durchführen.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(698,'esES','¡Naralex duerme nuevamente!$b$bHace tiempo, Naralex vino hasta esta caverna con el honorable fin de entrar en el Sueño Esmeralda y convertir los Baldíos en un bosque frondoso. Se le nubló la vista y sus pensamientos dieron paso a visiones serpenteantes.$b$bAhora, bestias reptiles descienden de sus sueños para penetrar en la tierra. Hay que despertarlo de la pesadilla o lo perderemos para siempre y se desatará un mal terrible.$b$bSolo después de matar a sus corruptos sirvientes, los Nobles del Colmillo, podré iniciar el ritual del despertar.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(698,'esMX','¡Naralex duerme nuevamente!$b$bHace tiempo, Naralex vino hasta esta caverna con el honorable fin de entrar en el Sueño Esmeralda y convertir los Baldíos en un bosque frondoso. Se le nubló la vista y sus pensamientos dieron paso a visiones serpenteantes.$b$bAhora, bestias reptiles descienden de sus sueños para penetrar en la tierra. Hay que despertarlo de la pesadilla o lo perderemos para siempre y se desatará un mal terrible.$b$bSolo después de matar a sus corruptos sirvientes, los Nobles del Colmillo, podré iniciar el ritual del despertar.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(698,'frFR','Naralex dort encore !$b$bIl y a bien longtemps, Naralex s’est rendu dans cette caverne dans le but honorable de pénétrer dans le Rêve d’émeraude et de redonner vie aux Tarides en les transformant en une forêt luxuriante. Sa concentration déclina et ses pensées furent infectées par des visions torturées.$b$bÀ présent, des créatures reptiliennes s’échappent de ses rêves pour s’infiltrer dans les terres. Il faut qu’il se réveille de ce cauchemar, autrement il sera perdu à jamais et un mal redoutable sera libéré.$b$bJe ne pourrai exécuter le rituel de réveil que lorsque ses serviteurs corrompus, les seigneurs-Croc, seront morts.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(698,'koKR','나랄렉스 님께서 또 잠이 드셨소!$B$B아주 오래전, 나랄렉스 님께서는 에메랄드의 꿈속으로 들어가 불모의 땅을 울창한 숲으로 만들겠다는 고귀한 뜻을 품고 이 동굴로 먼 길을 오셨소. 하지만 나랄렉스 님의 집중력이 약해지면서 뱀의 형상이 에메랄드의 꿈을 더럽히게 되었소.$B$B나랄렉스 님을 괴롭히는 그 파충류들이 이제는 이 땅까지 스며나오고 있소. 나랄렉스 님께서 악몽에서 깨어나지 않으면, 영원히 그분을 잃게 될 거요. 그러면 엄청난 악의 힘이 풀려나게 되겠지.$B$B나랄렉스 님을 반드시 깨워야 해! 하지만, 먼저 나랄렉스 님의 타락한 신하, 송곳니 군주들을 물리친 다음에야 그분을 깨우는 의식을 치를 수 있소.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(698,'zhCN','纳拉雷克斯又陷入了沉睡！$b$b很久以前，纳拉雷克斯曾满怀着进入翡翠梦境、让贫瘠之地重新变成茂密森林的伟大理想而来到了这处洞穴中。但他的执着却逐渐消退了，而他的思想也被脑海蜿蜒的影象所侵染。$b$b现在，那些奇怪的爬虫正从他的梦境中爬到这片土地上来，我们必须把他从梦魇中唤醒过来，否则他就将永远失落于其中，并继续给这片大地带来邪恶的力量！$b$b不过，只有杀死他那些堕落的仆人——毒牙之王，我才能开始进行唤醒仪式。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(698,'zhTW','納拉雷克斯又陷入了沉睡!$b$b很久以前，納拉雷克斯曾滿懷著進入翡翠夢境、讓貧瘠之地重新變成茂密森林的偉大理想而來到了這處洞穴中。但他的執著卻逐漸消退了，而他的思想也被腦海蜿蜒的幻象所侵染。$b$b現在，那些奇怪的爬蟲正從他的夢境中爬到這片土地上來，我們必須把他從夢魘中喚醒過來，否則他就將永遠失落於其中，並繼續給這片大地帶來邪惡的力量!$b$b不過，只有殺死他那些墮落的僕人─毒牙之王，我才能開始進行喚醒儀式。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'deDE',NULL,NULL,'Das Zählhaus Sturmwind findet Ihr in der Nähe der vorderen Tore im Handelsdistrikt von Sturmwind. Und wenn Ihr keine Lust mehr habt, Euer Geld zu zählen, dann schaut mal in der "Güldenen Rose" vorbei und genehmigt Euch einen Schluck.','Das Zählhaus Sturmwind findet Ihr in der Nähe der vorderen Tore im Handelsdistrikt von Sturmwind. Und wenn Ihr keine Lust mehr habt, Euer Geld zu zählen, dann schaut mal in der "Güldenen Rose" vorbei und genehmigt Euch einen Schluck.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'esES',NULL,NULL,'La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago.','La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'esMX',NULL,NULL,'La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago.','La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'frFR',NULL,NULL,'La Salle des dépôts de Hurlevent est située à l\'entrée du Quartier commerçant de Hurlevent. Quand vous en aurez assez de compter votre argent, n\'oubliez pas de vous arrêter à la Rose dorée pour prendre un verre.','La Salle des dépôts de Hurlevent est située à l\'entrée du Quartier commerçant de Hurlevent. Quand vous en aurez assez de compter votre argent, n\'oubliez pas de vous arrêter à la Rose dorée pour prendre un verre.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'koKR',NULL,NULL,'스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.','스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'zhCN',NULL,NULL,'暴风城的暴风城会计室位于城中贸易区的前门处。当你厌烦细数你的金钱时，一定要在镶金玫瑰喝一杯。','暴风城的暴风城会计室位于城中贸易区的前门处。当你厌烦细数你的金钱时，一定要在镶金玫瑰喝一杯。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(764,'zhTW',NULL,NULL,'暴風城的暴風城會計室位於城中貿易區的前門處。當你厭煩細數你的金錢時，一定要在鑲金玫瑰喝一杯。','暴風城的暴風城會計室位於城中貿易區的前門處。當你厭煩細數你的金錢時，一定要在鑲金玫瑰喝一杯。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(906,'deDE','Was? Ich weiß nichts über Hexenmeisterlehrer in Sturmwind. 

Obwohl... beim Geschlachteten Lamm drüben im Magierviertel gab es Sichtungen dämonischer Aktivitäten. Ihr solltet vielleicht dort einmal nachschauen.','Was? Ich weiß nichts über Hexenmeisterlehrer in Sturmwind. 

Obwohl... beim Geschlachteten Lamm drüben im Magierviertel gab es Sichtungen dämonischer Aktivitäten. Ihr solltet vielleicht dort einmal nachschauen.','Hexenmeister, hm? Also, Ihr habt das nicht von mir, aber ich hab Gerüchte gehört, dass sich diese Typen im Magierviertel in der Taverne \'Zum Geschlachteten Lamm\' treffen.','Hexenmeister, hm? Also, Ihr habt das nicht von mir, aber ich hab Gerüchte gehört, dass sich diese Typen im Magierviertel in der Taverne \'Zum Geschlachteten Lamm\' treffen.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(906,'esES','¿Qué? No conozco instructores brujos en Ventormenta. 

No obstante... dicen que se han celebrado actos demoníacos en El Cordero Degollado, en el Barrio de los Magos. Supongo que podrías mirar allí.','¿Qué? No conozco instructores brujos en Ventormenta. 

No obstante... dicen que se han celebrado actos demoníacos en El Cordero Degollado, en el Barrio de los Magos. Supongo que podrías mirar allí.','¿Brujos, eh? Bien, no digas que te lo he dicho yo, pero he oído rumores de que esos tipos se reúnen en una taberna llamada El Cordero Degollado, en el Barrio de los Magos.','¿Brujos, eh? Bien, no digas que te lo he dicho yo, pero he oído rumores de que esos tipos se reúnen en una taberna llamada El Cordero Degollado, en el Barrio de los Magos.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(906,'esMX','¿Qué? No conozco instructores brujos en Ventormenta. 
