(7365,'koKR','$n, 여기 자네의 점괘가 있으니 읽어보게. 현명하게 해석하길!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(7365,'zhCN','$n，这是你的塔罗牌。愿你能好好利用它。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
