Nuestra capacidad de reducir el daño que inflige un enemigo te ayudará a sobrevivir el Aliento agostador del protobehemoth.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(16952,'frFR','Il faut venger notre mère !

