(17159,'deDE','Für meinen Geschmack ist er ein wenig zu lebhaft.$B$BAber die Welt braucht Kinder, nehme ich an.$B$BWarum fragt Ihr?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(17159,'esES','Es un poco efusivo para mi gusto, pero en el mundo tiene que haber de todo, supongo.$b$b¿Por qué lo preguntas?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
