(20676,'deDE','Ein neuer Kontinent voller vergessener Geheimnisse! Teilt das, was Ihr lernt, mit den Lehrensuchern hier und mit mir, dann werde ich Euch ein paar meiner anderen Projekte offenbaren.','Ein neuer Kontinent voller vergessener Geheimnisse! Teilt das, was Ihr lernt, mit den Lehrensuchern hier und mit mir, dann werde ich Euch ein paar meiner anderen Projekte offenbaren.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(20676,'esES','¡Un continente nuevo lleno de secretos olvidados! Comparte tus descubrimientos con los eremitas y conmigo, y yo compartiré contigo algunos de mis otros proyectos.','¡Un continente nuevo lleno de secretos olvidados! Comparte tus descubrimientos con los eremitas y conmigo, y yo compartiré contigo algunos de mis otros proyectos.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
